sysauto_script.script:
(function() {
    // === Fetch Access Token ===
    var tokenGR = new GlideRecord("x_1803242_sample_u_cisco_csa_token");
    tokenGR.orderByDesc("sys_created_on");
    tokenGR.setLimit(1);
    tokenGR.query();

    if (!tokenGR.next()) {
        gs.error("No access token found");
        return;
    }
    var accessToken = tokenGR.getValue("access_token");

    // === Loop through destination lists ===
    var listGR = new GlideRecord("u_destination_list");
    listGR.query();

    while (listGR.next()) {
        var listId = listGR.getValue("u_list_id");
        var currentPage = parseInt(listGR.getValue("u_current_page") || "1");

        if (!listId) {
            gs.warn("Skipping list " + listGR.getDisplayValue("name") + " (no Cisco ID)");
            continue;
        }

        try {
            // Call Cisco API for current page
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint("https://api.sse.cisco.com/policies/v2/destinationlists/" + listId + "/destinations");
            r.setHttpMethod("GET");
            r.setRequestHeader("Authorization", "Bearer " + accessToken);
            r.setQueryParameter("limit", "100");
            r.setQueryParameter("page", currentPage.toString());

            var response = r.execute();
            var status = response.getStatusCode();
            var body = response.getBody();

            if (status == 200) {
                var parsed = JSON.parse(body);

                if (parsed.data && parsed.data.length > 0) {
                    for (var i = 0; i < parsed.data.length; i++) {
                        var item = parsed.data[i];

                        // Check duplicates by BOTH destination_id and destination string
                        var existing = new GlideRecord("u_destinations");
                        existing.addQuery("u_destination_list_id", listGR.sys_id);
                        existing.addQuery("u_destination", item.destination);
                        existing.query();

                        if (!existing.next()) {
                            var destGR = new GlideRecord("u_destinations");
                            destGR.initialize();
                            destGR.u_destination = item.destination;
                            destGR.u_destination_id = item.id;
                            destGR.u_destination_list_id = listGR.sys_id;
                            destGR.u_comment = item.comment;
                            destGR.insert();

                            gs.info("Inserted NEW destination: " + item.destination + " (" + item.id + ")");
                        } else {
                            gs.info("Skipped duplicate destination: " + item.destination);
                        }
                    }

                    gs.info("Processed page " + currentPage + " for list " + listId);

                    // Handle pagination
                    if (parsed.meta && parsed.meta.totalPages && currentPage < parsed.meta.totalPages) {
                        listGR.u_current_page = currentPage + 1;
                    } else {
                        listGR.u_current_page = 1; // Reset to 1 for next cycle
                        gs.info("Completed all pages for list " + listId + ". Resetting to 1");
                    }
                    listGR.update();
                } else {
                    gs.info("No data returned for page " + currentPage + " in list " + listId);
                    listGR.u_current_page = 1; 
                    listGR.update();
                }

            } else {
                gs.error("Cisco API error for list " + listId +
                         " | Status: " + status + " | Body: " + body);
            }

        } catch (e) {
            gs.error("Exception fetching list " + listId + " page " + currentPage +
                     " | " + (e.message || e.toString()));
        }
    }
})();
